CREATE OR REPLACE FUNCTION create_profile()
RETURNS TRIGGER AS $$
DECLARE
    domain TEXT;
BEGIN
    -- Check if the WebsiteUrl contains 'http://' and ends with '.com'
    IF NEW.WebsiteUrl LIKE 'http://%com' THEN
        -- Split the URL by '/'
        domain_parts := split_part(NEW.WebsiteUrl, '/', 3);

        -- Check if the domain_parts array has at least one element
        IF domain_parts IS NOT NULL AND domain_parts != '' THEN
            -- Split the domain_parts by '.'
            subdomain_parts := split_part(domain_parts, '.', 1);

            -- Check if the subdomain_parts array has at least one element
            IF subdomain_parts IS NOT NULL AND subdomain_parts != '' THEN
                -- Insert the profile into the profiles table
                INSERT INTO profiles (Id, CreationDate, WebsiteUrl)
                VALUES (NEW.id, NEW.creationdate, subdomain_parts);
            ELSE
                RAISE EXCEPTION 'Invalid WebsiteUrl format: %', NEW.WebsiteUrl;
            END IF;
        ELSE
            RAISE EXCEPTION 'Invalid WebsiteUrl format: %', NEW.WebsiteUrl;
        END IF;
    ELSE
        RAISE EXCEPTION 'Invalid WebsiteUrl format: %', NEW.WebsiteUrl;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

