CREATE OR REPLACE FUNCTION fn_concat(f_name character varying, l_name character varying) 
RETURNS character varying AS $$
DECLARE
    full_name character varying;
BEGIN
    -- Log input parameters
    RAISE NOTICE 'Input Parameters: f_name = %, l_name = %', f_name, l_name;

    -- Check if both names are provided
    IF f_name IS NOT NULL AND l_name IS NOT NULL THEN
        full_name := CONCAT(f_name, ' ', l_name);
    -- If only first name is provided
    ELSIF f_name IS NOT NULL AND l_name IS NULL THEN
        full_name := f_name;
    -- If only last name is provided
    ELSIF f_name IS NULL AND l_name IS NOT NULL THEN
        full_name := l_name;
    -- If neither name is provided
    ELSE
        full_name := NULL;
    END IF;

    -- Log the result
    RAISE NOTICE 'Result: full_name = %', full_name;

    RETURN full_name;
EXCEPTION
    WHEN OTHERS THEN
        -- Log any exceptions
        RAISE NOTICE 'Exception occurred: %', SQLERRM;
        RETURN NULL;
END;
$$ LANGUAGE plpgsql;

