  day_count INT := 0;
BEGIN
  FOR current_date IN start_date..end_date LOOP
    -- Check if the day is a weekend or a holiday
    IF EXTRACT(DOW FROM current_date) = 0 OR EXTRACT(DOW FROM current_date) = 6 THEN
      day_count := day_count + 1;
    ELSIF current_date IN ('2010-01-01', '2010-07-04', '2010-11-11', '2010-12-25',
