    id bigint,
    date date
);

-- Execute the PL/pgSQL block
DO $$
DECLARE
    v_id bigint;
    v_date date;
    json_data text;
    db_update_cursor CURSOR FOR
        SELECT id, date
        FROM laboratory
        ORDER BY id, date
        LIMIT 2;
BEGIN
    OPEN db_update_cursor;
    FETCH NEXT FROM db_update_cursor INTO v_id, v_date;
    WHILE FOUND LOOP
        -- Construct the JSON string
        json_data := json_build_object('id', v_id, 'date', v_date)::text;

        -- Insert the JSON string into the temporary table
        INSERT INTO temp_laboratory (id, date)
        VALUES (v_id, v_date);

        FETCH NEXT FROM db_update_cursor INTO v_id, v_date;
    END LOOP;

    CLOSE db_update_cursor;
END $$;

